"""Parse simple duration strings into whole seconds."""

import re

_UNIT_SECONDS = {"h": 3600, "m": 60, "s": 1}
_PATTERN = re.compile(r"(\d+(?:\.\d+)?)([hms])")


def parse_duration(text):
    """Convert strings like '1h30m', '45s' or '1.5h' into whole seconds.

    Raises ValueError if the text is not a valid combination of hours,
    minutes and seconds.
    """
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    total = 0
    pos = 0
    matched = False
    for match in _PATTERN.finditer(text):
        if match.start() != pos:
            raise ValueError(f"invalid duration: {text!r}")
        value, unit = match.groups()
        total += round(float(value) * _UNIT_SECONDS[unit])
        pos = match.end()
        matched = True

    if not matched or pos != len(text):
        raise ValueError(f"invalid duration: {text!r}")
    return total


def format_duration(seconds):
    """Convert whole seconds into the shortest string parse_duration accepts.

    For example 5400 becomes '1h30m' and 0 becomes '0s'.
    """
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("seconds must be an int")
    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    if seconds == 0:
        return "0s"

    parts = []
    remaining = seconds
    for unit in ("h", "m", "s"):
        value, remaining = divmod(remaining, _UNIT_SECONDS[unit])
        if value:
            parts.append(f"{value}{unit}")
    return "".join(parts)

#!/usr/bin/env python3
"""Read one duration per line from stdin, skip blank lines, print the total.

On an invalid line, print a message to stderr and exit with status 1.
"""

import sys

from durations import format_duration, parse_duration


def main() -> int:
    total = 0
    for line_no, line in enumerate(sys.stdin, start=1):
        text = line.strip()
        if not text:
            continue
        try:
            total += parse_duration(text)
        except ValueError:
            print(f"total.py: invalid duration on line {line_no}: {text}",
                  file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())


