            continue
        try:
            total += parse_duration(text)
        except ValueError:
            print(f"total.py: invalid duration on line {line_no}: {text}",
                  file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())


